    b=self.body(); cur=c.execute('insert into workspaces(slug,name,owner_id) values(?,?,?)',(b['slug'],b['name'],u['id'])); wid=cur.lastrowid;c.execute('insert into members values(?,?,?)',(wid,u['id'],'owner')); ch=c.execute('insert into channels(workspace_id,name) values(?,?)',(wid,'general'));c.execute('insert into cmembers values(?,?)',(ch.lastrowid,u['id']));c.commit(); return self.send(201,{'workspace':row(c.execute('select * from workspaces where id=?',(wid,)).fetchone()),'general_channel':row(c.execute('select * from channels where id=?',(ch.lastrowid,)).fetchone())})
   if p[1:3]==['api','workspaces'] and len(p)==3 and method=='GET':
    return self.send(200,{'workspaces':[row(x) for x in c.execute('select w.* from workspaces w join members m on m.workspace_id=w.id where m.user_id=?',(u['id'],))]})
   if p[1:3]==['api','workspaces'] and len(p)>=4:
    w=c.execute('select * from workspaces where slug=?',(p[3],)).fetchone()
    if not w:return self.send(404,{})
    if len(p)==4 and method=='GET':
     cs=[row(x) for x in c.execute('select * from channels where workspace_id=? and is_archived=0',(w['id'],))];return self.send(200,{'workspace':row(w),'channels':cs,'read_state':{}})
    if len(p)==5 and p[4]=='members': return self.send(200,{'members':[row(x) for x in c.execute('select user_id,role from members where workspace_id=?',(w['id'],))]})
    if len(p)==5 and p[4]=='channels' and method=='POST':
     b=self.body(); cur=c.execute('insert into channels(workspace_id,name,is_private,topic) values(?,?,?,?)',(w['id'],b['name'],int(b.get('is_private',False)),b.get('topic',''))); cid=cur.lastrowid;c.execute('insert into cmembers values(?,?)',(cid,u['id']));c.commit();return self.send(201,{'channel':row(c.execute('select * from channels where id=?',(cid,)).fetchone())})
   if p[1:3]==['api','channels'] and len(p)>=4:
    cid=int(p[3]); ch=c.execute('select * from channels where id=?',(cid,)).fetchone()
    if not ch:return self.send(404,{})
    if p[4:] == ['join'] and method=='POST': c.execute('insert or ignore into members values(?,?,?)',(ch['workspace_id'],u['id'],'member'));c.execute('insert or ignore into cmembers values(?,?)',(cid,u['id']));c.commit();return self.send(200,{'channel':row(ch)})
    if p[4:] == ['members']: return self.send(200,{'members':[user(x) for x in c.execute('select u.* from users u join cmembers m on m.user_id=u.id where m.channel_id=?',(cid,))]})
    if p[4:] == ['messages'] and method=='GET':
     lim=min(int(q.get('limit',['50'])[0]),200); ms=[msg(c,x) for x in c.execute('select * from messages where channel_id=? and deleted=0 order by id desc limit ?',(cid,lim))];return self.send(200,{'messages':ms,'next_cursor':None})
    if p[4:] == ['messages'] and method=='POST':
     b=self.body(); body=b.get('body','')
     if not body:return self.send(400,{'error':'empty'})
     eid=(c.execute('select coalesce(max(event_id),0)+1 n from messages where channel_id=?',(cid,)).fetchone()['n']);cur=c.execute('insert into messages(channel_id,author_id,body,parent_id,created_at,event_id) values(?,?,?,?,?,?)',(cid,u['id'],body,b.get('parent_id'),now(),eid));c.commit();return self.send(201,{'message':msg(c,c.execute('select * from messages where id=?',(cur.lastrowid,)).fetchone())})
   if p[1:3]==['api','messages'] and len(p)>=4:
    mid=int(p[3]); m=c.execute('select * from messages where id=?',(mid,)).fetchone()
    if not m:return self.send(404,{})
    if p[4:] == ['reactions'] and method=='POST':
     e=self.body().get('emoji');c.execute('insert or ignore into reactions values(?,?,?)',(mid,u['id'],e));c.commit();return self.send(200,{'reactions':msg(c,m)['reactions']})
    if p[4:] and p[4]=='reactions' and method=='DELETE':c.execute('delete from reactions where message_id=? and user_id=? and emoji=?',(mid,u['id'],p[5]));c.commit();return self.send(200,{'reactions':msg(c,m)['reactions']})
