   if p[1:3]==['api','search']: 
    term=q.get('q',[''])[0]; return self.send(200,{'results':[msg(c,x) for x in c.execute('select * from messages where body like ? and deleted=0 order by id desc',(f'%{term}%',))],'next_cursor':None})
